// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(true);
        bool opened = false;
        try c.OpenToThePublic() {
            opened = true;
        } catch {
            opened = false;
        }
        uint256 beforeBetLimit;
        try c.currentBetLimit() returns (uint256 __r) { beforeBetLimit = __r; } catch { return; }
        bool wagerReverted = false;
        if (amount > 0) {
            require(address(this).balance >= amount, "not enough balance to send");
        }
        try c.wager{value: amount}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }
        bool playReverted = false;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }
        assertTrue(wagerReverted || (amount == beforeBetLimit && playReverted));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
